// Screen of `menu.school_lms.courses` (F055 T031; F055-AC-13…AC-15): courses of the scope (listCourses by school /
// status), hide/show with lms.course.write (catalog action courses.edit), and a course's learning paths at
// `:courseId` (LearningPathBuilder). Courses are generated by the backend (class × subject, F040): no create here.
import { Button, Flex, Form, Select } from 'antd';
import type { ColumnType } from 'antd/es/table';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link, Route, Routes, useSearchParams } from 'react-router-dom';
import { ActionGate } from '../../../../permissions/ActionGate';
import { ResponsiveTable } from '../../common/ResponsiveTable';
import { SchoolSelect } from '../../common/SchoolSelect';
import { SingleTenantGate } from '../../common/scope';
import { PageTitle } from '../../common/ui';
import { useCourses, useUpdateCourseStatus, type Course } from '../api/courses';
import { courseLabel } from '../assignments/wizard/StepTargets';
import { LMS_ENUMS } from '../model/fieldSchemas';
import { LmsProblem, LmsTag } from '../LmsUi';
import { CourseDetailPage } from './CourseDetailPage';

function CourseListPage() {
  const { t, i18n } = useTranslation();
  const [params, setParams] = useSearchParams();
  const schoolId = params.get('school') ?? undefined;
  const [status, setStatus] = useState<Course['status'] | undefined>();
  const courses = useCourses({ schoolId, status });
  const update = useUpdateCourseStatus();
  const toggle = (c: Course) =>
    c.status === 'archived' ? null : (
      <ActionGate actionKey="action.school_lms.courses.edit">
        <Button size="small" loading={update.isPending && update.variables?.course.course_id === c.course_id} onClick={() => update.mutate({ course: c, status: c.status === 'active' ? 'hidden' : 'active' })}>
          {c.status === 'active' ? t('lms.course.hide') : t('lms.course.show')}
        </Button>
      </ActionGate>
    );
  const columns: ColumnType<Course>[] = [
    { key: 'name', title: t('lms.course.name'), render: (_, c) => <Link to={c.course_id}>{courseLabel(c, i18n.language)}</Link> },
    { key: 'status', title: t('lms.assignment.status'), render: (_, c) => <LmsTag group="courseStatus" value={c.status} /> },
    { key: 'students', title: t('lms.course.students'), render: (_, c) => c.student_count ?? '' },
    { key: 'actions', title: t('portal.school_lms.common.actions'), render: (_, c) => toggle(c) },
  ];
  return (
    <Flex vertical gap="middle">
      <Flex wrap="wrap" gap="middle">
        <Form.Item label={t('portal.school_lms.common.school')}>
          <SchoolSelect value={schoolId} onChange={(id) => setParams(id ? { school: id } : {}, { replace: true })} autoSelect={false} allowClear />
        </Form.Item>
        <Form.Item label={t('lms.assignment.status')}>
          <Select
            allowClear
            aria-label={t('lms.assignment.status')}
            value={status}
            onChange={setStatus}
            options={LMS_ENUMS.courseStatus.values.map((s) => ({ value: s, label: t(`lms.courseStatus.${s}`) }))}
          />
        </Form.Item>
      </Flex>
      <LmsProblem error={courses.error ?? update.error} />
      <ResponsiveTable<Course>
        rowKey="course_id"
        columns={columns}
        data={courses.items}
        loading={courses.isFetching}
        cardTitle={(c) => <Link to={c.course_id}>{courseLabel(c, i18n.language)}</Link>}
        hasMore={courses.hasMore}
        onLoadMore={courses.loadMore}
      />
    </Flex>
  );
}

export function CoursesScreen({ title }: { title: string }) {
  return (
    <section aria-labelledby="ew-menu-title">
      <PageTitle title={title} />
      <SingleTenantGate>
        {() => (
          <Routes>
            <Route index element={<CourseListPage />} />
            <Route path=":courseId" element={<CourseDetailPage />} />
          </Routes>
        )}
      </SingleTenantGate>
    </section>
  );
}
